from typing import List

def solve(tokens: List[str]) -> int:
    """Stack of numbers not yet consumed. A number is pushed; an operator pops its two operands
    (the right operand was pushed last, so it comes off first), computes, and pushes the result.
    One pass: O(n) time, O(n) space."""
    stack = []
    for tok in tokens:
        if tok in {"+", "-", "*", "/"}:
            b, a = stack.pop(), stack.pop()
            if tok == "+":
                val = a + b
            elif tok == "-":
                val = a - b
            elif tok == "*":
                val = a * b
            else:
                # int(a / b) truncates toward zero; a // b would floor -7 / 2 to -4 instead of -3
                val = int(a / b)
            stack.append(val)
        else:
            stack.append(int(tok))
    return stack[-1]

def demo():
    return solve(["2", "1", "+", "3", "*"])

print(demo())

from typing import List

def solve(temps: List[int]) -> List[int]:
    """Stack of indices still waiting for a warmer day; their temperatures decrease bottom to top.
    Each index is pushed once and popped once: O(n)."""
    n = len(temps)
    answer = [0] * n
    waiting = []  # indices; temps[waiting] is decreasing from bottom to top
    for i, t in enumerate(temps):
        while waiting and temps[waiting[-1]] < t:
            j = waiting.pop()
            answer[j] = i - j
        waiting.append(i)
    return answer

