def solve(root):
    """BFS with a queue: at the top of each round the queue holds exactly one level, so pop len(q) nodes
    while their children queue up behind. O(n) time, O(width) space."""
    if root is None:
        return []
    levels, q = [], deque([root])
    while q:
        level = []
        for _ in range(len(q)):
            node = q.popleft()
            level.append(node.val)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        levels.append(level)
    return levels

