import heapq
from typing import List

def sift_down(a: List[int], i: int, n: int) -> None:
    """Move a[i] down while a child is smaller; stop at a leaf or when both children are >= it."""
    while True:
        l, r, smallest = 2 * i + 1, 2 * i + 2, i
        if l < n and a[l] < a[smallest]:
            smallest = l
        if r < n and a[r] < a[smallest]:
            smallest = r
        if smallest == i:
            return
        a[i], a[smallest] = a[smallest], a[i]
        i = smallest

def solve(nums: List[int]) -> List[int]:
    """Floyd's build: sift down every internal node, last parent first, root last. O(n) total."""
    a = list(nums)
    n = len(a)
    for i in range(n // 2 - 1, -1, -1):
        sift_down(a, i, n)
    return a

def demo():
    return solve([9, 4, 7, 1, 2, 6, 3])

print(demo())

import heapq
from typing import List, Optional

def push(heap: List[int], x: int) -> None:
    """Append at the end, then swap up while the parent is bigger. O(log n)."""
    heap.append(x)
    i = len(heap) - 1
    while i > 0 and heap[(i - 1) // 2] > heap[i]:
        p = (i - 1) // 2
        heap[i], heap[p] = heap[p], heap[i]
        i = p

def pop(heap: List[int]) -> int:
    """Take the root, put the last element there, then sink it toward the smaller child. O(log n)."""
    top, last = heap[0], heap.pop()
    if heap:
        heap[0] = last
    i, n = 0, len(heap)
    while True:
        c = 2 * i + 1
        if c + 1 < n and heap[c + 1] < heap[c]:
            c += 1
        if c >= n or heap[i] <= heap[c]:
            break
        heap[i], heap[c] = heap[c], heap[i]
        i = c
    return top

def solve(ops: List[Optional[int]]) -> List[int]:
    """Drive the hand-rolled heap; returns the popped values in order."""
    heap, popped = [], []
    for op in ops:
        if op is None:
            popped.append(pop(heap))
        else:
            push(heap, op)
    return popped

def demo():
    return solve([5, 3, 8, None, 1, None, None])

print(demo())

import heapq
from typing import List

def solve(nums: List[int], k: int) -> List[int]:
    """Min-heap of the k largest so far; the root is the gatekeeper. O(n log k)."""
    heap = []
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heappushpop(heap, x)
    return sorted(heap)

def demo():
    return solve([3, 1, 5, 12, 2, 11], 3)

