import heapq
from typing import List

class KthLargest:
    """Min-heap of the k largest values seen; its root is the k-th largest. add is O(log k)."""

    def __init__(self, k: int, nums: List[int]):
        self.k = k
        self.heap = []
        for x in nums:
            self.add(x)

    def add(self, val: int) -> int:
        heapq.heappush(self.heap, val)
        if len(self.heap) > self.k:
            dropped = heapq.heappop(self.heap)
        return self.heap[0]

def solve(k: int, nums: List[int], adds: List[int]) -> List[int]:
    kth = KthLargest(k, nums)
    return [kth.add(v) for v in adds]

def demo():
    return solve(3, [4, 5, 8, 2], [3, 5, 10, 9, 4])

print(demo())

import heapq
from typing import List

def solve(arrays: List[List[int]]) -> List[int]:
    """One candidate per array in a heap keyed (value, which array, position). O(N log k)."""
    heap = [(arr[0], i, 0) for i, arr in enumerate(arrays) if arr]
    heapq.heapify(heap)
    out = []
    while heap:
        val, i, j = heapq.heappop(heap)
        out.append(val)
        if j + 1 < len(arrays[i]):
            heapq.heappush(heap, (arrays[i][j + 1], i, j + 1))
    return out

def demo():
    return solve([[1, 4, 7], [2, 5], [0, 8, 9]])

print(demo())

from typing import List, Optional, Tuple

class ListNode:
    def __init__(self, val=0, next=None):
        self.val, self.next = val, next

def build_list(values):
    dummy = tail = ListNode()
    for v in values:
        tail.next = tail = ListNode(v)
    return dummy.next

def to_list(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out

def draw(head): return " -> ".join(map(str, to_list(head))) or "empty"

def insert_at(head: Optional[ListNode], index: int, val: int) -> Optional[ListNode]:
    """Walk index steps from a dummy so prev is the node before the slot; splice after it. O(index)."""
    prev = dummy = ListNode(0, head)
    for _ in range(index):
        prev = prev.next
    prev.next = ListNode(val, prev.next)
    return dummy.next

def delete_val(head: Optional[ListNode], val: int) -> Optional[ListNode]:
    """Walk prev from a dummy until prev.next holds val; unlink it by skipping over it. O(n)."""
    prev = dummy = ListNode(0, head)
    while prev.next and prev.next.val != val:
        prev = prev.next
    if prev.next:
        prev.next = prev.next.next
    return dummy.next

def solve(ops: List[Tuple]) -> List[List[int]]:
    """Apply the ops on nodes; a dummy head makes index 0 and the head deletion ordinary cases."""
    head, snapshots = None, []
    for op in ops:
        if op[0] == "insert":
            head = insert_at(head, op[1], op[2])
        else:
            head = delete_val(head, op[1])
        snapshots.append(to_list(head))
