    total = 0
    for i in range(n + 1):  # i == n is the sentinel that pops everything
        while stack and (i == n or nums[stack[-1]] >= nums[i]):
            j = stack.pop()
            left = stack[-1] if stack else -1
            total += nums[j] * (j - left) * (i - j)
