    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    seen, count = set(), 0
    for s in range(n):
        if s in seen:
            continue
        count += 1
        seen.add(s)
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in seen:
                    seen.add(v)
                    q.append(v)
    return count

def demo():
    return solve(7, [(0, 1), (1, 2), (3, 4)])

print(demo())

from collections import deque
from typing import List

def solve(mat):
    """Multi-source BFS: all zeros start in the queue with distance 0; every other cell is reached once, in its layer. O(m*n)."""
    m, n = len(mat), len(mat[0])
    dist = [[0 if v == 0 else -1 for v in row] for row in mat]
    q = deque((r, c) for r in range(m) for c in range(n) if mat[r][c] == 0)
    while q:
        for _ in range(len(q)):
            r, c = q.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < m and 0 <= nc < n and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
    return dist

