def solve(nums: List[int]) -> List[int]:
    """Sorted prefix grows by one each round; the new element walks left to its slot. O(n^2), stable."""
    a = list(nums)
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

