def solve(path: str) -> str:
    """Stack of directory names: '..' pops (if anything is there), '' and '.' are skipped, names are pushed. O(n)."""
    stack = []
    for part in path.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return "/" + "/".join(stack)

