def solve(s: str) -> str:
    """One stack of (string built before the bracket, repeat count); ']' pops it and glues prefix + cur * count. O(output length)."""
    stack = []
    cur, k = "", 0
    for ch in s:
        if ch.isdigit():
            k = k * 10 + int(ch)
        elif ch == "[":
            stack.append((cur, k))
            cur, k = "", 0
        elif ch == "]":
            prev, cnt = stack.pop()
            cur = prev + cur * cnt
        else:
            cur += ch
    return cur

