def insert(root, v):
    if root is None:
        return TreeNode(v)
    if v < root.val:
        root.left = insert(root.left, v)
    elif v > root.val:
        root.right = insert(root.right, v)
    return root

def search(root, v):
    while root and root.val != v:
        root = root.left if v < root.val else root.right
    return root is not None

def delete(root, v):
    if root is None:
        return None
    if v < root.val:
        root.left = delete(root.left, v)
    elif v > root.val:
        root.right = delete(root.right, v)
    elif root.left is None or root.right is None:
        return root.left or root.right
    else:
        succ = root.right
        while succ.left:
            succ = succ.left
        root.val = succ.val
        root.right = delete(root.right, succ.val)
    return root

def inorder(n): return inorder(n.left) + [n.val] + inorder(n.right) if n else []

def solve(ops):
    """Each op descends one root-to-leaf path: O(height) per op, O(n) for the final inorder."""
    root, found = None, []
