from collections import deque

class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right


def build_tree(vals):  # level order, None = missing child (LeetCode style)
    nodes = [TreeNode(v) if v is not None else None for v in vals]
    kids = iter(nodes[1:])
    for node in nodes:
        if node:
            node.left, node.right = next(kids, None), next(kids, None)
    return nodes[0] if nodes else None

def serialize(root):
    """Preorder tokens, '#' for a missing child, joined by commas. O(n)."""
    out = []

    def rec(node):
        if node is None:
            out.append("#")
            return
        out.append(str(node.val))
        rec(node.left)
        rec(node.right)
    rec(root)
    return ",".join(out)

def deserialize(data):
    """One iterator shared by every call consumes the tokens in preorder; '#' closes a branch. O(n)."""
    tokens = iter(data.split(","))

    def rec():
        tok = next(tokens)
        if tok == "#":
            return None
        node = TreeNode(int(tok))
        node.left = rec()
        node.right = rec()
        return node
    return rec()

def solve(root):
    """Round trip: encode, decode, encode again; the two strings must match."""
    data = serialize(root)
    again = serialize(deserialize(data))
    assert again == data, (data, again)
    return data

def demo():
    return solve(build_tree([1, 2, 3, None, None, 4, 5]))

print(demo())

from typing import List, Optional, Tuple

class TrieNode:
    def __init__(self):
        self.children = {}  # char -> TrieNode
        self.end = False    # a word ends here

def to_dict(node):  # nested dict view for the trace; "$" marks a word end
    d = {"$": True} if node.end else {}
    d.update((c, to_dict(n)) for c, n in node.children.items())
    return d

def insert(root: TrieNode, word: str) -> None:
    node = root
    for ch in word:
        if ch not in node.children:
            node.children[ch] = TrieNode()
        node = node.children[ch]
    node.end = True

def find(root: TrieNode, s: str) -> Optional[TrieNode]:
    node = root
    for ch in s:
        if ch not in node.children:
            return None
        node = node.children[ch]
    return node

def search(root: TrieNode, word: str) -> bool:
    node = find(root, word)
    return node is not None and node.end

def starts_with(root: TrieNode, prefix: str) -> bool:
    return find(root, prefix) is not None

def solve(ops: List[Tuple[str, str]]) -> List[bool]:
    """Each op walks at most len(word) nodes: O(len) per op, independent of how many words are stored."""
    root, out = TrieNode(), []
    for op, word in ops:
        if op == "insert":
            insert(root, word)
        elif op == "search":
            out.append(search(root, word))
        else:
            out.append(starts_with(root, word))
    return out

def demo():
    return solve([("insert", "apple"), ("search", "apple"), ("search", "app"),
                  ("startsWith", "app"), ("insert", "app"), ("search", "app")])

print(demo())

from typing import List

class TrieNode:
    def __init__(self):
        self.children = {}  # char -> TrieNode
        self.end = False    # a word ends here

def to_dict(node):  # nested dict view; "$" marks a word end
    d = {"$": True} if node.end else {}
    d.update((c, to_dict(n)) for c, n in node.children.items())
    return d

def insert(root: TrieNode, word: str) -> None:
    node = root
    for ch in word:
        if ch not in node.children:
            node.children[ch] = TrieNode()
        node = node.children[ch]
    node.end = True

def delete(root: TrieNode, word: str) -> bool:
    """Record the path down; clear the flag; walk back up deleting nodes that are empty and end no word. O(len)."""
    path = [root]
    for ch in word:
        if ch not in path[-1].children:
            return False
        path.append(path[-1].children[ch])
    if not path[-1].end:
        return False
    path[-1].end = False
    for i in range(len(word) - 1, -1, -1):
        node, child = path[i], path[i + 1]
        if child.children or child.end:
            break
        del node.children[word[i]]
    return True

def solve(words: List[str], removals: List[str]) -> dict:
    """Insert everything, delete each removal (missing words are no-ops), return the trie as a nested dict."""
    root = TrieNode()
    for w in words:
        insert(root, w)
    for w in removals:
        delete(root, w)
    return to_dict(root)

def demo():
    return solve(["apple", "app", "ape"], ["apple", "app", "cat"])

print(demo())

from typing import List

class TrieNode:
    def __init__(self):
        self.children = {}  # char -> TrieNode
        self.end = False    # a word ends here

def to_dict(node):  # nested dict view; "$" marks a word end
    d = {"$": True} if node.end else {}
    d.update((c, to_dict(n)) for c, n in node.children.items())
    return d

def insert(root: TrieNode, word: str) -> None:
    node = root
    for ch in word:
        if ch not in node.children:
            node.children[ch] = TrieNode()
        node = node.children[ch]
    node.end = True

def solve(words: List[str], prefix: str) -> List[str]:
    """Build the trie, walk the prefix (O(len)), then DFS only the matching subtree (O(output size))."""
    root = TrieNode()
    for w in words:
        insert(root, w)
    node = root
    for ch in prefix:
        if ch not in node.children:
            return []
        node = node.children[ch]
    out = []

    def dfs(node, path):
        if node.end:
            out.append(path)
        for ch in sorted(node.children):
            dfs(node.children[ch], path + ch)
    dfs(node, prefix)
    return out

def demo():
    return solve(["car", "card", "care", "cat", "dog"], "car")

print(demo())

from typing import List, Tuple

class TrieNode:
    def __init__(self):
